package com.votehub.config;
import com.votehub.entity.*;import com.votehub.repository.*;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import java.time.*;
@Configuration public class DataInitializer { @Bean CommandLineRunner seed(ElectionRepository er,CandidateRepository cr){return args->{if(er.count()>0)return;LocalDateTime now=LocalDateTime.now();Election live=new Election();live.name="Student Council Election 2026";live.description="Live demonstration election for VoteHub.";live.startTime=now.minusMinutes(10);live.endTime=now.plusHours(2);live.status=Election.Status.ACTIVE;er.save(live);for(String n:new String[]{"Aarav Sharma","Diya Reddy","Rahul Verma"}){Candidate c=new Candidate();c.election=live;c.name=n;c.position="Student Council President";c.description="Candidate profile and programme information.";cr.save(c);}Election old=new Election();old.name="Cultural Committee Election 2026";old.description="Completed previous election for history/results demonstration.";old.startTime=now.minusDays(10);old.endTime=now.minusDays(9);old.status=Election.Status.CLOSED;old.resultsPublished=true;er.save(old);for(String n:new String[]{"Meera Singh","Kiran Rao"}){Candidate c=new Candidate();c.election=old;c.name=n;c.position="Cultural Committee";c.description="Previous election candidate.";cr.save(c);}};}}
